// Topic-specific facts. Each entry adds precision to the branch-level scaffold.
type AtlasEntry = {
  definition?: string
  intuition?: string
  visual?: string
  math?: string[]
  theorem?: string
  proof?: string
  example?: string
  application?: string
  mistake?: string
  question?: string
  history?: string
  code?: string
  derivation?: string
  method?: string
  status?: string
  assumption?: string
}

export const TOPIC_ATLAS: Record<string, AtlasEntry> = {
  // ── Foundations ─────────────────────────────────────────────────────────
  'whole-numbers': { definition: `The whole numbers are 0, 1, 2, … — the natural numbers together with zero.`, math: [String.raw`0\in\mathbb N,\qquad n\in\mathbb N\Rightarrow n+1\in\mathbb N`, String.raw`a+(b+c)=(a+b)+c`], intuition: `Zero is not "nothing" in a metaphysical sense; it is the additive identity, the number whose existence makes subtraction a total operation on ℕ only after extending to ℤ.`, mistake: `Treating division by zero like any other division — it is undefined because 0 has no multiplicative inverse.`, question: `Why is 0 the only number that cannot be a divisor?` },
  'irrational-numbers': { definition: `An irrational number is a real number that is not a ratio of two integers.`, theorem: `√2 is irrational. Proof: if √2 = p/q in lowest terms then p² = 2q², so p and q are both even — contradicting coprimality.`, example: `√2 ≈ 1.41421356; its decimal expansion is non-terminating and non-repeating.`, question: `Why must the reals contain numbers the rationals do not?` },
  'real-numbers': { definition: `ℝ is the unique (up to isomorphism) complete ordered field.`, intuition: `Completeness — every bounded nonempty set has a least upper bound — is what makes limits work. ℚ fails: the set {x ∈ ℚ : x² < 2} is bounded but has no rational supremum.`, theorem: `The monotone convergence theorem and the intermediate value theorem both follow from completeness.`, question: `Which calculus theorems would fail over ℚ?` },
  'number-systems': { definition: `A number system is a set equipped with operations satisfying specified axioms; the classical chain is ℕ ⊂ ℤ ⊂ ℚ ⊂ ℝ ⊂ ℂ.`, visual: `Draw each system as a nested region; annotate the equation that forces each extension.`, question: `What equation is unsolvable in each system but solvable in the next?` },
  'binary-hexadecimal': { definition: `Base-b representation writes n = Σ dᵢ bⁱ with digits 0 ≤ dᵢ < b.`, example: `13 in binary is 1101 (8+4+1); in hexadecimal it is D.`, code: `print(bin(13), hex(13))  # 0b1101 0xd`, application: `Computer memory addresses and colour codes use hexadecimal as compact binary.` },
  'exponents-powers': { definition: `aⁿ is a multiplied by itself n times; the definition extends to negative and fractional exponents by preserving aᵐaⁿ = aᵐ⁺ⁿ.`, theorem: `a^{m/n} = (root n of a)^m for a ≥ 0.`, mistake: `(a+b)ⁿ ≠ aⁿ + bⁿ except in characteristic p settings — the binomial terms matter.` },
  'roots-radicals': { definition: `√[n]{a} is the nonnegative x with xⁿ = a (for a ≥ 0, n even).`, derivation: `√(ab) = √a√b follows from (√a√b)² = ab and uniqueness of nonnegative roots.`, question: `Why is √(−1) not a real number?` },
  'logarithms': { definition: `log_b x is the exponent y with bʸ = x, for b > 0, b ≠ 1, x > 0.`, theorem: `log_b(xy) = log_b x + log_b y; change of base: log_b x = ln x / ln b.`, application: `Decibels, pH and the Richter scale are logarithmic because they compress multiplicative ranges.`, mistake: `log(a+b) ≠ log a + log b.` },
  'prime-numbers': { definition: `A prime is an integer p > 1 whose only positive divisors are 1 and p.`, theorem: `Euclid: infinitely many primes. If p₁…pₙ were all, then p₁…pₙ + 1 has a prime factor not on the list.`, example: `The first six primes are 2, 3, 5, 7, 11, 13; 2·3·5·7·11·13 + 1 = 30031 = 59·509.`, question: `Why can a product of primes plus one be composite yet still prove the theorem?` },
  'modular-arithmetic': { definition: `a ≡ b (mod n) means n divides a − b; residues form a ring ℤ/nℤ.`, theorem: `a has an inverse mod n iff gcd(a,n)=1; Euler: a^{φ(n)} ≡ 1 mod n.`, example: `7·11 = 77 ≡ 5 (mod 12); 3 has no inverse mod 6.`, application: `RSA and check-digit systems rely on modular invertibility.` },
  'percentages': { definition: `p% means p/100; a percentage is a ratio expressed with denominator 100.`, example: `A 20% increase from 250 gives 250·1.2 = 300; reversing it is 300/1.2 = 250, not 300·0.8.`, mistake: `A 20% rise followed by a 20% fall does not return to the original value.` },
  'ratios-proportions': { definition: `A proportion is an equality of two ratios: a/b = c/d ⇒ ad = bc when b,d ≠ 0.`, example: `If 3 kg cost ₹180, then 5 kg cost 180·5/3 = ₹300.` },
  'order-of-operations': { definition: `Parentheses, exponents, multiplication/division left-to-right, addition/subtraction left-to-right.`, intuition: `The convention exists so that an expression has a unique value; it is not a law of nature but a shared grammar.` },
  'mathematical-notation': { definition: `Notation is a compressed language: quantifiers ∀, ∃; implication ⇒; set membership ∈.`, example: `∀ε>0 ∃δ>0 : |x−a|<δ ⇒ |f(x)−L|<ε states the limit definition without words.`, history: `Modern notation is largely due to Leibniz, Euler and Peano.` },
  'coordinate-basics': { definition: `The Cartesian plane assigns each point an ordered pair (x,y) measuring signed horizontal and vertical distance from an origin.`, visual: `Every algebraic equation in x,y becomes a geometric locus.`, question: `Why does (x,y) determine a unique point?` },
  'rational-expressions': { definition: `A rational expression is a quotient P(x)/Q(x) of polynomials with Q ≠ 0.`, theorem: `The domain excludes zeros of Q; simplification can create removable holes but cannot restore excluded points.`, mistake: `Cancelling (x−1) from (x²−1)/(x−1) loses the hole at x=1.` },
  'exponential-equations': { definition: `Equations with the unknown in an exponent, solved by applying logarithms.`, example: `2ˣ = 32 ⇒ x = log₂32 = 5; 3^{2x−1} = 27 ⇒ 2x−1 = 3 ⇒ x = 2.` },
  'logarithmic-equations': { definition: `Equations involving logarithms; solve by exponentiating and checking the domain.`, mistake: `log(x−3) = 1 gives x = 13 only if x−3 > 0 — always verify.`, example: `ln(x) + ln(x−1) = ln 6 ⇒ x(x−1)=6 ⇒ x=3.` },
  'systems-of-equations': { definition: `A set of equations solved simultaneously; the solution is the intersection of their solution sets.`, method: `Elimination and substitution are equivalent to applying invertible row operations.`, example: `x+y=5, x−y=1 ⇒ x=3, y=2.` },
  'algebraic-identities': { definition: `An identity is an equality true for all admissible values of the variables.`, math: [String.raw`(a+b)^2=a^2+2ab+b^2`, String.raw`a^3+b^3=(a+b)(a^2-ab+b^2)`], question: `How do you distinguish an identity from an equation?` },
  'algebraic-inequalities': { definition: `An inequality compares ordered quantities; multiplying by a negative reverses the order.`, theorem: `AM–GM: for positive xᵢ, (Σxᵢ)/n ≥ (Πxᵢ)^{1/n} with equality iff all xᵢ equal.`, example: `For x>0, x + 1/x ≥ 2 with equality at x=1.` },
  'absolute-value': { definition: `|x| is the distance of x from 0; |x| = x if x ≥ 0, else −x.`, theorem: `|x+y| ≤ |x|+|y| (triangle inequality); |xy| = |x||y|.` },
  'euclidean-geometry': { definition: `Geometry based on Euclid's postulates, including the parallel postulate.`, history: `Euclid's Elements (c. 300 BCE) organised geometry into definitions, postulates and deductive proofs.`, question: `What happens if the parallel postulate is replaced?` },
  'plane-geometry': { definition: `The study of figures in a two-dimensional Euclidean plane: angles, triangles, circles and polygons.`, theorem: `The angles of a triangle sum to 180°; the exterior angle equals the sum of the opposite interior angles.` },
  'solid-geometry': { definition: `Three-dimensional Euclidean geometry: planes, polyhedra, spheres and volume.`, math: [String.raw`V_{\text{sphere}}=\tfrac43\pi r^3`, String.raw`V_{\text{cone}}=\tfrac13\pi r^2h`] },
  'coordinate-geometry': { definition: `Geometry expressed algebraically by assigning coordinates and translating loci into equations.`, example: `A circle of radius r centred at (a,b): (x−a)²+(y−b)²=r².` },
  'analytic-geometry': { definition: `The use of algebra and coordinates to solve geometric problems; distance, slope and conic equations are its basic tools.`, math: [String.raw`d=\sqrt{(x_2-x_1)^2+(y_2-y_1)^2}`, String.raw`m=\frac{y_2-y_1}{x_2-x_1}`] },
  'polygons': { definition: `A polygon is a closed plane figure bounded by finitely many line segments.`, theorem: `The interior angles of an n-gon sum to (n−2)·180°; the exterior angles sum to 360°.` },
  'transformations': { definition: `A transformation maps points to points; isometries preserve distance, similarities preserve shape.`, math: [String.raw`T(x,y)=(x+h,y+k)`, String.raw`R_\theta(x,y)=(x\cos\theta-y\sin\theta,\ x\sin\theta+y\cos\theta)`] },
  'congruence': { definition: `Two figures are congruent if a rigid motion (translation, rotation, reflection) maps one onto the other.`, theorem: `Triangles are congruent by SSS, SAS, ASA or AAS.` },
  'similarity': { definition: `Similar figures have the same shape: corresponding angles equal and sides in a constant ratio k.`, theorem: `Areas scale by k² and volumes by k³.`, example: `Two similar triangles with scale 3 have area ratio 9.` },
  'geometric-constructions': { definition: `Constructions produce geometric objects using only an unmarked straightedge and compass.`, history: `The Greeks distinguished constructible numbers; Wantzel proved angle trisection impossible in 1837.` },
  'non-euclidean-geometry': { definition: `Geometries that replace Euclid's parallel postulate, notably hyperbolic and elliptic geometry.`, intuition: `On a sphere, "lines" are great circles and they always meet — the parallel postulate fails, and triangle angles exceed 180°.`, history: `Gauss, Bolyai and Lobachevsky discovered hyperbolic geometry in the nineteenth century.` },
  'angles': { definition: `An angle measures the amount of rotation between two rays; one radian is the angle subtending an arc equal to the radius.`, math: [String.raw`\theta_{\text{rad}}=\frac{s}{r}`, String.raw`180^\circ=\pi\ \text{rad}`] },
  'radians-degrees': { definition: `Degrees divide a turn into 360 parts; radians use arc length per radius, making calculus formulas clean.`, example: `90° = π/2 rad; 60° = π/3 rad; sin(π/6) = 1/2.` },
  'inverse-trigonometric-functions': { definition: `arcsin, arccos and arctan invert the trig functions on restricted branches.`, mistake: `sin(arcsin x) = x only for x ∈ [−1,1]; arcsin(sin x) need not equal x outside [−π/2,π/2].` },
  'trigonometric-equations': { definition: `Equations whose solutions use periodicity and the unit circle; general solutions include integer multiples of the period.`, example: `sin x = 1/2 ⇒ x = π/6 + 2kπ or x = 5π/6 + 2kπ.` },
  'trig-graphs': { definition: `Graphs of sine, cosine and tangent; amplitude, period, phase and vertical shift are read from y = A sin(Bx + C) + D.`, math: [String.raw`T=\frac{2\pi}{|B|}`] },
  'law-of-sines': { definition: `In any triangle, a/sin A = b/sin B = c/sin C = 2R.`, application: `Solve a triangle given two angles and one side.` },
  'law-of-cosines': { definition: `c² = a² + b² − 2ab cos C; generalises the Pythagorean theorem.`, derivation: `Place the triangle in coordinates with C at the origin and expand the distance formula.`, example: `With a=3, b=4, C=60°, c²=9+16−24·0.5=13, so c≈3.606.` },
  'hyperbolic-functions': { definition: `sinh x = (eˣ − e⁻ˣ)/2, cosh x = (eˣ + e⁻ˣ)/2.`, math: [String.raw`\cosh^2x-\sinh^2x=1`, String.raw`\frac{d}{dx}\sinh x=\cosh x`] },
  'polar-coordinates': { definition: `A point is described by (r, θ) with x = r cos θ, y = r sin θ.`, application: `Conics and central-force orbits have simple polar equations.` },
  'parametric-curves': { definition: `A curve traced by (x(t), y(t)) as t varies; the parameter carries timing information.`, math: [String.raw`\frac{dy}{dx}=\frac{dy/dt}{dx/dt}`] },
  'fourier-connections': { definition: `Trigonometric functions form an orthogonal basis; Fourier series expand periodic functions in sines and cosines.`, math: [String.raw`f(x)=\frac{a_0}{2}+\sum_{n\ge1}\left(a_n\cos nx+b_n\sin nx\right)`] },

  // ── Core university ─────────────────────────────────────────────────────
  'differentiability': { definition: `f is differentiable at a if the difference quotient has a finite limit there.`, theorem: `Differentiability implies continuity; continuity does not imply differentiability (e.g. |x| at 0).`, question: `Give an example of a continuous nowhere-differentiable function.` },
  'product-rule': { definition: `(fg)′ = f′g + fg′.`, derivation: `Add and subtract f(x+h)g(x) in the difference quotient, then take limits using continuity of g.`, example: `(x² sin x)′ = 2x sin x + x² cos x.` },
  'quotient-rule': { definition: `(f/g)′ = (f′g − fg′)/g² for g ≠ 0.`, derivation: `Rewrite f/g as f·g⁻¹ and apply product and chain rules.` },
  'implicit-differentiation': { definition: `Differentiate both sides of F(x,y)=0 treating y as a function of x, then solve for y′.`, example: `x²+y²=25 ⇒ 2x+2yy′=0 ⇒ y′=−x/y.` },
  'higher-order-derivatives': { definition: `Repeated derivatives f′, f″, …; f″ measures curvature of the graph.`, application: `Acceleration is the second derivative of position.` },
  'related-rates': { definition: `Differentiate a geometric relation with respect to time to connect rates.`, example: `For a sphere V=4πr³/3, dV/dt=4πr² dr/dt.` },
  'lhopital-rule': { definition: `For 0/0 or ∞/∞ forms, lim f/g = lim f′/g′ provided the latter exists.`, mistake: `It applies only to indeterminate forms — not to 0/5 or ∞/0.` },
  'curve-sketching': { definition: `Use derivatives to determine monotonicity, concavity, extrema and asymptotes before plotting.`, method: `Solve f′=0 for critical points and f″=0 for inflection points.` },
  'antiderivatives': { definition: `F is an antiderivative of f on an interval if F′=f there; antiderivatives differ by a constant on connected intervals.`, example: `An antiderivative of 3x² is x³ + C.` },
  'substitution': { definition: `∫f(g(x))g′(x)dx = ∫f(u)du with u=g(x).`, intuition: `The chain rule read backwards: substitute the inner function and its derivative cancels.` },
  'improper-integrals': { definition: `Integrals with unbounded intervals or integrands, defined as limits.`, example: `∫₁^∞ x⁻² dx = lim_{b→∞}[−1/x]₁ᵇ = 1.` },
  'arc-length': { definition: `L = ∫ₐᵇ √(1+(f′)²) dx for a smooth planar curve.`, derivation: `Sum chord lengths of a fine partition and take the limit.` },
  'numerical-integration': { definition: `Approximate definite integrals by quadrature rules: trapezoid, midpoint, Simpson.`, math: [String.raw`\text{Simpson: }\frac{h}{3}\left(f_0+4f_1+2f_2+\cdots+4f_{n-1}+f_n\right)`] },
  'uniform-convergence': { definition: `fₙ → f uniformly if sup|fₙ−f| → 0; this is stronger than pointwise convergence.`, theorem: `Uniform limits of continuous functions are continuous and may be integrated term-by-term.` },
  'power-series': { definition: `Σ aₙ(x−c)ⁿ; its radius of convergence R is given by 1/R = limsup |aₙ|^{1/n}.`, example: `Σ xⁿ/n! converges for all x; Σ xⁿ converges only for |x|<1.` },
  'partial-derivatives': { definition: `∂f/∂x differentiates with all other variables held fixed.`, example: `For f=x²y+y³, fₓ=2xy and fᵧ=x²+3y².` },
  'directional-derivatives': { definition: `D_u f = ∇f · u for a unit vector u; it is the rate of change in direction u.`, theorem: `The maximum directional derivative is ‖∇f‖ in the direction of the gradient.` },
  'jacobian': { definition: `The matrix of all first partial derivatives of a vector-valued function; its determinant gives local volume scaling.`, application: `Change of variables in multiple integrals: dx dy = |det J| du dv.` },
  'hessian': { definition: `The square matrix of second partial derivatives; its definiteness classifies critical points.`, theorem: `At a critical point, positive definite Hessian ⇒ local minimum; negative definite ⇒ local maximum.` },
  'multiple-integrals': { definition: `Integrals over regions in ℝⁿ; Fubini's theorem reduces them to iterated integrals under integrability.`, math: [String.raw`\iint_R f\,dA=\int_a^b\int_{c(x)}^{d(x)}f(x,y)\,dy\,dx`] },
  'greens-theorem': { definition: `∮_C(P dx + Q dy) = ∬_D(Qₓ − Pᵧ)dA for a positively oriented simple closed curve C.`, application: `Compute area as ½∮(x dy − y dx).` },
  'stokes-theorem': { definition: `∮_{∂S} F·dr = ∬_S (∇×F)·n dS.`, intuition: `The circulation around a boundary equals the total curl through the surface.` },
  'divergence-theorem': { definition: `∭_V ∇·F dV = ∬_{∂V} F·n dS.`, application: `Flux of a field through a closed surface equals total source strength inside.` },
  'vector-spaces': { definition: `A set with vector addition and scalar multiplication satisfying eight axioms.`, example: `ℝⁿ, polynomials of degree ≤ n and continuous functions on [0,1] are all vector spaces.` },
  'span': { definition: `span(v₁,…,vₖ) is the set of all linear combinations; it is the smallest subspace containing the vectors.` },
  'linear-independence': { definition: `Vectors are independent if Σ cᵢvᵢ = 0 forces all cᵢ = 0.`, theorem: `A set of more than n vectors in ℝⁿ is dependent.` },
  'matrix-multiplication': { definition: `(AB)ᵢⱼ = Σₖ Aᵢₖ Bₖⱼ; composition of linear maps corresponds to matrix product in matching bases.`, mistake: `Matrix multiplication is not commutative.` },
  'determinants': { definition: `det A is the signed volume scaling factor of the linear map; det A = 0 iff A is singular.`, math: [String.raw`\det\begin{pmatrix}a&b\\c&d\end{pmatrix}=ad-bc`] },
  'rank': { definition: `The dimension of the column space; equals the number of pivots in row echelon form.`, theorem: `Rank–nullity: rank(A) + nullity(A) = number of columns.` },
  'null-space': { definition: `{x : Ax = 0}; its dimension is the nullity.`, application: `Solutions of Ax=b are a particular solution plus the null space.` },
  'diagonalization': { definition: `A = PDP⁻¹ with D diagonal when A has a basis of eigenvectors.`, theorem: `An n×n matrix with n distinct eigenvalues is diagonalisable.` },
  'orthogonality': { definition: `u ⟂ v iff ⟨u,v⟩ = 0; orthogonal sets are linearly independent (if nonzero).` },
  'gram-schmidt': { definition: `An algorithm converting a linearly independent set into an orthonormal set spanning the same subspace.`, math: [String.raw`v_k=u_k-\sum_{j<k}\frac{\langle u_k,e_j\rangle}{\langle e_j,e_j\rangle}e_j`] },
  'qr-decomposition': { definition: `A = QR with Q orthonormal columns and R upper triangular; obtained from Gram–Schmidt.` },
  'lu-decomposition': { definition: `A = LU with L lower triangular and U upper triangular, when Gaussian elimination needs no row swaps.`, application: `Efficient repeated solving of Ax = b for many b.` },
  'spectral-theorem': { definition: `A real symmetric matrix has an orthonormal eigenbasis: A = QΛQᵀ.`, application: `Principal component analysis diagonalises a covariance matrix.` },
  'propositional-logic': { definition: `The study of propositions and connectives ∧, ∨, ¬, ⇒ with truth-functional semantics.`, theorem: `p ⇒ q is logically equivalent to ¬p ∨ q and to its contrapositive ¬q ⇒ ¬p.` },
  'predicate-logic': { definition: `Extends propositional logic with quantifiers ∀, ∃ and predicates over a domain.`, mistake: `¬∀x P(x) ≡ ∃x ¬P(x); the negation moves inside, not stays outside.` },
  'set-theory': { definition: `Sets are collections; membership, subsets, union, intersection and complement form the basic algebra.`, math: [String.raw`|A\cup B|=|A|+|B|-|A\cap B|`] },
  'relations': { definition: `A relation on A×B is a set of ordered pairs; reflexivity, symmetry and transitivity classify relations.`, theorem: `An equivalence relation partitions the set into disjoint equivalence classes.` },
  'mathematical-induction': { definition: `If P(1) holds and P(k) ⇒ P(k+1) for all k, then P(n) holds for all n ≥ 1.`, example: `1+2+…+n = n(n+1)/2; add (k+1) to the inductive hypothesis and simplify.` },
  'recursion': { definition: `A definition where each term is specified in terms of earlier terms plus base cases.`, example: `Fibonacci: F₀=0, F₁=1, Fₙ=Fₙ₋₁+Fₙ₋₂; F₁₀=55.` },
  'permutations': { definition: `An ordered arrangement of k objects chosen from n; P(n,k)=n!/(n−k)!.` },
  'inclusion-exclusion': { definition: `|A∪B∪C| = Σ|A| − Σ|A∩B| + |A∩B∩C|.`, application: `Count integers divisible by at least one of several primes.` },
  'boolean-algebra': { definition: `A complemented distributive lattice; its operations ∧, ∨, ¬ obey idempotence and De Morgan's laws.`, application: `Digital circuit design and database queries.` },
  'automata-theory': { definition: `An automaton is a finite-state machine reading symbols and changing state according to a transition function.`, theorem: `Regular languages are exactly those recognised by finite automata.` },
  'computational-complexity': { definition: `Classifies problems by resources (time, space) required; P is polynomial-time, NP is polynomial-time verifiable.`, question: `Why is P ⊆ NP, and why is equality unresolved?` },
  'sample-spaces': { definition: `The set Ω of all possible outcomes of an experiment; events are subsets of Ω.`, example: `Two dice: Ω has 36 ordered pairs.` },
  'events': { definition: `An event is a measurable subset of the sample space; probability is a measure on events.` },
  'independence': { definition: `A and B are independent iff P(A∩B) = P(A)P(B).`, mistake: `Independence is not disjointness; disjoint positive-probability events cannot be independent.` },
  'variance': { definition: `Var(X) = E[(X−E X)²] = E[X²] − (E X)².`, example: `For a fair die, E[X]=3.5 and Var(X)=35/12 ≈ 2.917.` },
  'covariance-correlation': { definition: `Cov(X,Y)=E[(X−EX)(Y−EY)]; correlation normalises covariance to [−1,1].`, mistake: `Correlation zero does not imply independence.` },
  'moment-generating-functions': { definition: `M_X(t)=E[e^{tX}]; its derivatives at 0 give moments when it exists near 0.`, theorem: `MGFs determine distributions under suitable conditions and M_{X+Y}=M_X M_Y for independent X,Y.` },
  'central-limit-theorem': { definition: `For i.i.d. finite-variance Xᵢ, (X̄ₙ−μ)/(σ/√n) converges in distribution to N(0,1).`, application: `Justifies normal approximations for averages and polling margins.` },
  'law-large-numbers': { definition: `Sample averages converge to the expected value (weakly in probability, strongly almost surely).`, intuition: `Random fluctuation averages out as sample size grows.` },
  'markov-chains': { definition: `A stochastic process with the Markov property: the next state depends only on the current state.`, theorem: `An irreducible aperiodic finite chain has a unique stationary distribution π=πP.` },
  'bayesian-probability': { definition: `Probability as degree of belief updated by Bayes' rule: posterior ∝ likelihood × prior.`, example: `A 1% prior with a 10:1 likelihood ratio gives posterior odds ≈ 1:9.` },
  'estimation': { definition: `Use sample data to approximate an unknown parameter; estimators are assessed by bias, variance and consistency.`, example: `The sample mean is unbiased for μ with variance σ²/n.` },
  'hypothesis-testing': { definition: `A procedure with a null hypothesis, test statistic and controlled Type I error rate α.`, mistake: `A p-value is P(data as extreme | H₀), not P(H₀ | data).` },
  'confidence-intervals': { definition: `A random interval containing the true parameter with specified long-run frequency.`, example: `x̄ ± 1.96σ/√n is an approximate 95% interval for a normal mean.` },
  'logistic-regression': { definition: `Models P(y=1|x) = σ(βᵀx) with the sigmoid σ(z)=1/(1+e⁻ᶻ).`, application: `Binary classification with interpretable log-odds coefficients.` },
  'anova': { definition: `Analysis of variance compares group means by decomposing total variation into between- and within-group components.`, math: [String.raw`F=\frac{\text{MS}_{\text{between}}}{\text{MS}_{\text{within}}}`] },
  'causal-inference': { definition: `Reasoning about interventions, not merely associations; formalised by potential outcomes or causal graphs.`, mistake: `Adjusting for a collider can create spurious association.` },

  // ── Advanced pure ───────────────────────────────────────────────────────
  'subgroups': { definition: `A subgroup H ≤ G is a subset closed under the group operation and inverses, containing e.`, theorem: `Lagrange: |H| divides |G| for finite groups.` },
  'cyclic-groups': { definition: `A group generated by one element: G = ⟨g⟩.`, example: `ℤ/nℤ is cyclic of order n, generated by 1.` },
  'permutation-groups': { definition: `The group Sₙ of bijections of {1,…,n} under composition; |Sₙ|=n!.`, theorem: `Cayley: every finite group embeds in a symmetric group.` },
  'group-homomorphisms': { definition: `A map φ:G→H with φ(ab)=φ(a)φ(b); its kernel is a normal subgroup.`, theorem: `First isomorphism theorem: G/ker φ ≅ im φ.` },
  'quotient-groups': { definition: `G/N for a normal subgroup N; elements are cosets gN.`, intuition: `Quotienting forgets information inside N and keeps only the coset.` },
  'rings': { definition: `A set with two operations, addition an abelian group, multiplication associative and distributive over addition.`, example: `ℤ, polynomial rings and n×n matrices are rings.` },
  'ideals': { definition: `An additive subgroup I of a ring with rI ⊆ I for all r; ideals are kernels of ring homomorphisms.`, theorem: `R/I is a ring; I is prime iff R/I is an integral domain.` },
  'fields': { definition: `A commutative ring in which every nonzero element is invertible.`, example: `ℚ, ℝ, ℂ and ℤ/pℤ (p prime) are fields.` },
  'field-extensions': { definition: `A field L containing K, viewed as a K-vector space; its dimension is [L:K].`, example: `[ℂ:ℝ]=2 with basis {1,i}.` },
  'galois-theory': { definition: `The correspondence between intermediate fields of a Galois extension and subgroups of its automorphism group.`, theorem: `A polynomial is solvable by radicals iff its Galois group is solvable.` },
  'category-theory': { definition: `Categories consist of objects and morphisms with composition and identities; functors preserve this structure.`, example: `The category of vector spaces has linear maps as morphisms.` },
  'congruences': { definition: `a ≡ b (mod n) iff n | (a−b); congruence is an equivalence relation compatible with + and ×.`, theorem: `Chinese remainder theorem: coprime moduli allow independent solution of simultaneous congruences.` },
  'diophantine-equations': { definition: `Polynomial equations seeking integer or rational solutions.`, theorem: `ax+by=c has integer solutions iff gcd(a,b) | c.`, example: `3x+5y=1 has solution x=2, y=−1.` },
  'chinese-remainder-theorem': { definition: `For coprime m,n the system x≡a (mod m), x≡b (mod n) has a unique solution mod mn.`, example: `x≡2 mod 3, x≡3 mod 5 ⇒ x≡8 mod 15.` },
  'fermats-little-theorem': { definition: `For prime p and p ∤ a: a^{p−1} ≡ 1 (mod p).`, application: `Reduce huge powers modulo a prime.` },
  'eulers-theorem': { definition: `gcd(a,n)=1 ⇒ a^{φ(n)} ≡ 1 (mod n).`, application: `RSA correctness relies on this and the Chinese remainder theorem.` },
  'riemann-zeta-function': { definition: `ζ(s)=Σ n^{−s} for Re(s)>1, extended meromorphically to ℂ with a functional equation.`, math: [String.raw`\zeta(s)=\sum_{n=1}^\infty n^{-s}`, String.raw`\zeta(s)=2^s\pi^{s-1}\sin(\pi s/2)\Gamma(1-s)\zeta(1-s)`] },
  'metric-spaces': { definition: `A set with a distance d satisfying positivity, symmetry and triangle inequality.`, example: `Euclidean, Manhattan and discrete metrics on ℝⁿ.` },
  'compactness': { definition: `Every open cover admits a finite subcover; in ℝⁿ equivalent to closed and bounded.`, theorem: `A continuous function on a compact set attains its maximum and minimum.` },
  'connectedness': { definition: `A space is connected if it cannot be split into two disjoint nonempty open sets.`, theorem: `Continuous images of connected sets are connected (intermediate value theorem).` },
  'completeness': { definition: `Every Cauchy sequence converges (metric form); every bounded set has a supremum (order form).`, example: `ℝ is complete; ℚ is not: approximations to √2 are Cauchy in ℚ but converge outside it.` },
  'lebesgue-integration': { definition: `Integration by slicing the range, built on measure; handles limits far better than Riemann integration.`, theorem: `Dominated convergence: if |fₙ| ≤ g integrable and fₙ→f a.e., then ∫fₙ→∫f.` },
  'holomorphic-functions': { definition: `Complex differentiable in a neighbourhood of every point; equivalent to analytic.`, theorem: `Holomorphic functions are infinitely differentiable and satisfy Cauchy's integral formula.` },
  'cauchy-riemann': { definition: `For f=u+iv, holomorphy is equivalent to uₓ=vᵧ and uᵧ=−vₓ with continuous partials.`, application: `Check whether a given complex function is analytic.` },
  'contour-integration': { definition: `∫_γ f(z)dz along a path; for holomorphic f in a simply connected domain it is path-independent.`, theorem: `Cauchy's theorem: ∮ f = 0 when f is holomorphic inside and on a simple closed curve.` },
  'cauchy-integral-formula': { definition: `f(a) = (1/2πi) ∮ f(z)/(z−a) dz for holomorphic f inside a simple closed curve.`, intuition: `The value inside is determined entirely by boundary data.` },
  'conformal-mappings': { definition: `Holomorphic maps with nonzero derivative preserve angles locally.`, application: `Map complicated domains to discs to solve boundary-value problems.` },
  'residue-theorem': { definition: `∮_γ f = 2πi Σ Res(f,aₖ) over isolated singularities inside γ.`, example: `Res(1/(z²+1), i) = 1/(2i), giving ∮ = π for a contour enclosing i only.` },
  'banach-spaces': { definition: `Complete normed vector spaces.`, theorem: `Banach fixed point: a contraction on a complete metric space has a unique fixed point.` },
  'hilbert-spaces': { definition: `Complete inner-product spaces; generalise Euclidean geometry to infinite dimensions.`, theorem: `The projection theorem: every closed convex set has a nearest point.` },
  'topological-spaces': { definition: `A set with a collection of open sets containing ∅ and the whole set, closed under arbitrary unions and finite intersections.`, intuition: `Topology is geometry with distance forgotten.` },
  'homotopy': { definition: `A continuous deformation between maps; homotopic maps induce the same maps on homotopy groups.`, example: `The circle is homotopy equivalent to an annulus.` },
  'fundamental-groups': { definition: `The group of loop classes up to homotopy, with concatenation.`, example: `π₁(S¹)=ℤ, π₁(S²)=0.` },
  'homology': { definition: `Assign abelian groups to spaces measuring holes of each dimension, invariant under homotopy equivalence.`, example: `H₁(S¹)=ℤ, H₂(S²)=ℤ.` },
  'manifolds': { definition: `A space locally homeomorphic to ℝⁿ with compatible charts.`, example: `The sphere is a 2-manifold; spacetime is a 4-manifold.` },
  'knot-theory': { definition: `The study of embeddings of circles in 3-space up to ambient isotopy.`, example: `The trefoil knot is distinct from the unknot, detected by the Jones polynomial.` },
  'tangent-spaces': { definition: `The vector space of velocities of curves through a point on a manifold.`, intuition: `A tangent space linearises a curved space at one point.` },
  'differential-forms': { definition: `Antisymmetric tensor fields integrated over oriented manifolds; generalised integrands.`, math: [String.raw`d^2=0`, String.raw`\int_{\partial M}\omega=\int_M d\omega`] },
  'tensor-calculus': { definition: `Index-based calculus for multilinear objects transforming covariantly or contravariantly.`, application: `Expressing physical laws independently of coordinates.` },
  'connections': { definition: `A rule for differentiating vector fields along curves on a manifold, giving parallel transport.`, example: `The Levi-Civita connection is torsion-free and metric-compatible.` },
  'curvature': { definition: `The failure of parallel transport to be path-independent; Riemann curvature measures it locally.`, math: [String.raw`[\nabla_X,\nabla_Y]Z-\nabla_{[X,Y]}Z=R(X,Y)Z`] },
  'godel-incompleteness': { definition: `Any consistent recursively axiomatisable theory strong enough for arithmetic has true statements it cannot prove.`, status: `Theorem, not a conjecture.` },
  'computability-theory': { definition: `The study of what can be computed by an effective procedure; Turing machines provide the model.`, theorem: `The halting problem is undecidable.` },
  'cardinality': { definition: `Two sets have the same cardinality if a bijection exists between them.`, theorem: `Cantor: |ℝ| > |ℕ|; |P(S)| > |S|.` },
  'zfc-axioms': { definition: `Zermelo–Fraenkel set theory with the axiom of choice, the standard foundation of modern mathematics.`, intuition: `Axioms restrict which collections count as sets to avoid paradoxes such as Russell's.` },

  // ── Applied, real world, research ───────────────────────────────────────
  'floating-point': { definition: `Finite-precision approximation of reals: x ≈ m·2ᵉ with bounded mantissa.`, example: `In IEEE double, machine epsilon ≈ 2.22×10⁻¹⁶; 0.1+0.2 ≠ 0.3 exactly.`, mistake: `Comparing floats for exact equality.` },
  'root-finding': { definition: `Locate x with f(x)=0; bracketing gives guarantees, Newton gives speed.`, theorem: `Bisection halves the interval each step: error ≤ (b−a)/2ⁿ.` },
  'newton-raphson': { definition: `x_{n+1}=xₙ−f(xₙ)/f′(xₙ); quadratic convergence near a simple root.`, mistake: `It can diverge when f′ is near zero or the initial guess is poor.` },
  'interpolation': { definition: `Construct a function passing through given data points; polynomial interpolation is the classical case.`, theorem: `Error for degree-n polynomial interpolation involves f^{(n+1)}(ξ)∏(x−xᵢ)/(n+1)!.` },
  'finite-difference': { definition: `Replace derivatives by differences on a grid; consistency follows from Taylor expansion.`, math: [String.raw`f'(x)\approx\frac{f(x+h)-f(x-h)}{2h}`] },
  'first-order-ode': { definition: `y′=f(x,y) with an initial condition; separable and linear families have explicit solution methods.`, theorem: `Picard–Lindelöf: existence and uniqueness when f is Lipschitz in y.` },
  'stability-theory': { definition: `Classification of equilibria by the eigenvalues of the linearisation; Lyapunov methods handle nonlinear cases.`, example: `For x′=−x, the equilibrium 0 is asymptotically stable.` },
  'bifurcation-theory': { definition: `Qualitative change in the solution structure as a parameter crosses a critical value.`, example: `The logistic map x↦rx(1−x) enters period doubling near r≈3.57.` },
  'linear-programming': { definition: `Optimise a linear objective over a polyhedron defined by linear constraints.`, theorem: `An optimum occurs at a vertex; the simplex method exploits this.` },
  'duality': { definition: `Every linear program has a dual whose optimum bounds the primal; under feasibility and boundedness they coincide (strong duality).`, math: [String.raw`\min\{c^Tx:Ax\ge b\}\ =\ \max\{b^Ty:A^Ty\le c\}`] },
  'lagrange-multipliers': { definition: `At a constrained extremum, ∇f is a linear combination of constraint gradients.`, example: `Maximise xy on x+y=10: ∇f=(y,x)=λ(1,1) ⇒ x=y=5.` },
  'shannon-entropy': { definition: `H(X)=−Σ p(x) log₂ p(x), the expected information content in bits.`, theorem: `H(X) ≤ log₂|range(X)| with equality for the uniform distribution.` },
  'error-correcting-codes': { definition: `Add structured redundancy so that corrupted messages can be decoded.`, example: `Hamming(7,4) corrects any single-bit error using parity checks.` },
  'graph-coloring': { definition: `Assign colours to vertices so adjacent vertices differ; the chromatic number χ(G) is the minimum needed.`, theorem: `Four colour theorem: every planar graph satisfies χ(G) ≤ 4.` },
  'network-flows': { definition: `Send flow through a capacitated network maximising flow from source to sink.`, theorem: `Max-flow equals min-cut (Ford–Fulkerson).` },
  'random-graphs': { definition: `G(n,p) includes each possible edge independently with probability p.`, theorem: `For p=(log n + c)/n the giant component emerges; connectivity threshold at p≈log n/n.` },
  'mixed-strategies': { definition: `Players randomise over actions; equilibrium makes each player indifferent among supported actions.`, example: `Matching pennies has a unique mixed equilibrium: both randomise 50/50.` },
  'mechanism-design': { definition: `Design rules so that self-interested agents' equilibrium behaviour yields a desired outcome.`, theorem: `Revelation principle: implementation can be assumed direct and truthful.` },
  'black-scholes': { definition: `Price of a European call under lognormal dynamics: C = SΦ(d₁) − Ke^{−rT}Φ(d₂).`, assumption: `No dividends, constant r and σ, frictionless markets — all idealisations that must be stated.` },
  'portfolio-optimization': { definition: `Choose asset weights maximising expected return for a given risk (variance).`, math: [String.raw`\min_w w^T\Sigma w\quad\text{s.t. }w^T\mu=R,\ w^T\mathbf1=1`] },
  'epidemiological-models': { definition: `Compartmental ODE models (SIR, SEIR) tracking populations through disease stages.`, theorem: `An epidemic grows iff R₀ S/N > 1; final size solves 1−R∞ = e^{−R₀(1−R∞)}.` },
  'population-dynamics': { definition: `Models of population change: exponential, logistic and predator–prey systems.`, math: [String.raw`\frac{dN}{dt}=rN\left(1-\frac{N}{K}\right)`] },
  'transformers-math': { definition: `Attention computes softmax(QKᵀ/√dₖ)V; layers compose affine maps with pointwise nonlinearities.`, question: `Why does the 1/√dₖ scaling stabilise training?` },
  'statistical-learning-theory-ai': { definition: `Bounds generalisation risk using empirical risk plus a capacity term.`, math: [String.raw`R(f)\le\widehat R(f)+\mathcal O\!\left(\sqrt{\frac{\text{complexity}}{n}}\right)`] },
  'optimal-transport': { definition: `Move mass between distributions minimising a transport cost; Kantorovich duality gives a linear-programming formulation.`, application: `Generative modelling via flow and diffusion models.` },
  'riemann-hypothesis-frontier': { definition: `Conjecture: every nontrivial zero of ζ(s) has Re(s)=1/2.`, status: `Open. Verified numerically for vast ranges — evidence is not proof.`, question: `What would a proof reveal about the error term in the prime number theorem?` },
  'p-vs-np': { definition: `Open question: is every problem whose solution can be verified in polynomial time also solvable in polynomial time?`, status: `Open; P ⊆ NP is trivial, equality is unknown.` },
  'collatz-conjecture': { definition: `Iterate n↦n/2 (even) or 3n+1 (odd); the conjecture says every start reaches 1.`, status: `Open; extensively verified computationally.` },
  'navier-stokes-problem': { definition: `Open problem of global smooth solutions to the 3D incompressible Navier–Stokes equations.`, status: `Open; one of the Clay Millennium Problems.` },
  'langlands-program': { definition: `A web of conjectures relating Galois representations to automorphic forms and L-functions.`, status: `Research programme with major theorems in special cases.` },
  'quantum-computing-foundations': { definition: `Quantum computation uses unitary operators on tensor products of qubits; measurement yields eigenvalues.`, theorem: `No-cloning theorem: an unknown quantum state cannot be copied perfectly.` },
}


export function atlasBlocks(
  id: string, branchId: string, title: string, summary: string,
  equations: string[], prereqs: string[], siblings: string[],
  level: Level,
): Block[] {
  const b = BRANCH_ATLAS[branchId] ?? BRANCH_ATLAS.arithmetic
  const a = TOPIC_ATLAS[id] ?? {}
  const clean = (s: string) => s.replace(/^\s*\d+\s*·\s*/, '')
  const methods = a.method ? [a.method, ...b.methods].slice(0, 3) : b.methods
  const blocks: Block[] = [
    { kind: 'heading', text: '1 · Why this topic exists' },
    { kind: 'paragraph', text: summary },
    { kind: 'callout', tone: 'intuition', title: 'The question it answers', text: `${title} belongs to the study of ${b.object}. Its guiding question is: ${b.question} ${a.intuition ?? ''}`.trim() },
    { kind: 'callout', tone: 'history', title: 'Historical motivation', text: a.history ?? b.history },

    { kind: 'heading', text: '2 · What you will be able to do' },
    { kind: 'list', items: [
      `State the definition of ${title.toLowerCase()} precisely and explain each hypothesis.`,
      `Derive its central relations rather than memorising them: ${b.methods.slice(0, 2).join(' and ')}.`,
      `Recognise it inside a larger problem and connect it to ${siblings.slice(0, 2).map(s => s.replace(/-/g, ' ')).join(' and ') || 'adjacent ideas'}.`,
      `Implement a numerical or symbolic experiment and state what the result does and does not prove.`,
    ] },

    { kind: 'heading', text: '3 · Prerequisites and logical order' },
    { kind: 'paragraph', text: prereqs.length
      ? `This lesson assumes ${prereqs.map(x => x.replace(/-/g, ' ')).join(', ')}. Each prerequisite supplies a piece of the language used here; if any is unfamiliar, open it first and return.`
      : `This is a starting point: no prior topic is required beyond ordinary arithmetic and the willingness to question definitions.` },

    { kind: 'heading', text: '4 · Intuitive understanding' },
    { kind: 'paragraph', text: a.intuition ?? `Think of ${title.toLowerCase()} as the answer to a pressure point in ${b.object}. Earlier tools worked for simpler cases; this topic isolates exactly the new feature that makes the harder case tractable. The core ideas are: ${b.ideas.map(clean).join(' ')}` },

    { kind: 'heading', text: '5 · Visual and geometric understanding' },
    { kind: 'callout', tone: 'visual', title: 'See it', text: a.visual ?? b.visual },

    { kind: 'heading', text: '6 · Definition and notation' },
    { kind: 'paragraph', text: a.definition ?? `${title} is the precise mathematical object used in ${b.object} to make the question "${b.question}" answerable. The definition fixes which objects belong to the theory and which maps between them are allowed — everything afterwards is a consequence of those choices.` },
    ...(equations.length ? [{ kind: 'heading' as const, text: '7 · Mathematical formulation' },
      ...equations.map(eq => ({ kind: 'math' as const, latex: eq, display: true })),
    ] : [{ kind: 'heading' as const, text: '7 · Mathematical formulation' },
      { kind: 'math' as const, latex: b.ideas.join('\n\\;\n'), display: true, caption: `Canonical relations for ${title.toLowerCase()} within ${branchId.replace(/-/g, ' ')}.` }]),
    ...(a.math ?? []).map(eq => ({ kind: 'math' as const, latex: eq, display: true })),

    { kind: 'heading', text: '8 · Derivation from first principles' },
    { kind: 'steps', title: `Constructing ${title.toLowerCase()}`, items: methods.map((m, i) => ({
      title: `Step ${i + 1} · ${m}`,
      text: i === 0 ? `Begin with the definition and isolate the invariant the method exploits. ${a.derivation ?? a.proof ?? ''}` : i === 1 ? `Apply the method to a concrete instance, tracking every hypothesis. ${a.assumption ?? ''}` : `State the result and check which assumptions were actually used.`,
      math: b.ideas[i] ?? b.ideas[0],
    })) },

    { kind: 'heading', text: '9 · Theorems and proof structure' },
    { kind: 'paragraph', text: `${a.status ? `${a.status} ` : ''}${a.theorem ?? `The standard results in ${title.toLowerCase()} are statements that a property holds for every object satisfying the definition. Their proofs follow the pattern: unpack definitions, apply ${b.methods[0]}, and verify the hypotheses. A proof sketch is not a proof — reconstruct the missing lines yourself.`}` },
    { kind: 'callout', tone: 'note', title: 'Proof discipline', text: a.proof ?? `When you read a theorem here, list its hypotheses, find where each is used, and try to construct a counterexample when one is removed. That is how genuine understanding is tested.` },

    { kind: 'heading', text: '10 · Worked example' },
    { kind: 'paragraph', text: a.example ?? b.example },
    { kind: 'code', language: 'python', code: a.code ?? b.code, caption: `A computational check for ${title.toLowerCase()}. Symbolic and numerical work supports understanding; it never replaces proof.` },

    { kind: 'heading', text: '11 · Real-world applications' },
    { kind: 'list', items: [a.application, ...b.applications].filter(Boolean) as string[] },

    { kind: 'heading', text: '12 · Common mistakes' },
    { kind: 'callout', tone: 'warning', title: 'Watch for these', text: `${a.mistake ?? ''} ${b.pitfalls.join(' ')}`.trim() },

    { kind: 'heading', text: '13 · Conceptual questions' },
    { kind: 'list', ordered: true, items: [
      a.question ?? `Which property in ${title.toLowerCase()} is invariant under the maps allowed by its definition?`,
      `Which hypothesis in the main theorem would fail first in a counterexample?`,
      `Where does this topic appear as a prerequisite later in ${branchId.replace(/-/g, ' ')}?`,
    ] },

    { kind: 'heading', text: '14 · Practice and further reading' },
    { kind: 'list', items: [
      `Reproduce the worked example without consulting the text, then change one parameter.`,
      `Prove one of the listed relations from the definition alone.`,
      `Open the linked resources and compare their treatment of ${title.toLowerCase()} with this one.`,
    ] },
    { kind: 'paragraph', text: `Continue with ${siblings.slice(0, 4).map(s => s.replace(/-/g, ' ')).join(', ') || 'the neighbouring topics'} in this branch, or use the knowledge graph to find an alternative route. Level: ${level}.` },
  ]
  return blocks
}
